// Deliberately independent of the private owner application. No portfolio import.
const fs=require('node:fs'),path=require('node:path');
const dest=path.resolve('public-site/dist');fs.mkdirSync(dest,{recursive:true});
const css=`:root{--ink:#193f38;--muted:#52655e;--paper:#f7f5ef;--line:#d8ded5;--accent:#dce9a9}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.65 system-ui,-apple-system,Segoe UI,sans-serif}a{color:inherit;text-underline-offset:4px}header,main,footer{max-width:1160px;margin:auto;padding:26px 32px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}.brand{font-weight:800;font-size:25px;letter-spacing:-1px;text-decoration:none}.brand span{color:#63866a}nav{display:flex;gap:24px;font-size:14px}h1{font-size:clamp(42px,6.5vw,80px);line-height:1.06;letter-spacing:-3px;max-width:850px;margin:22px 0}h2{font-size:clamp(28px,4vw,43px);line-height:1.18;letter-spacing:-1px}h3{font-size:21px}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase;font-weight:750}.hero{padding:72px 0 64px;display:grid;grid-template-columns:1.6fr 1fr;gap:50px;align-items:center}.lead{font-size:21px;max-width:630px;color:var(--muted)}.button{display:inline-block;background:var(--ink);color:white;text-decoration:none;border-radius:8px;padding:13px 21px;margin:12px 10px 0 0;font-weight:650;font-size:15px}.button.secondary{background:transparent;color:var(--ink);border:1px solid var(--ink)}.status{border:1px solid #b5c1a4;border-radius:24px;padding:5px 13px;display:inline-block;font-size:12px;font-weight:700}.board{background:#e9ede3;padding:25px;border-radius:18px;transform:rotate(2deg)}.board h3{margin:5px 0 22px}.row{background:#fffdf7;padding:16px;border-radius:10px;margin:10px 0;display:flex;justify-content:space-between;gap:12px;font-size:14px}.tag{color:#53713d;font-size:12px}.caption{font-size:12px;color:var(--muted)}section{padding:48px 0;border-top:1px solid var(--line)}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:30px}.grid article{padding:4px 0}.number{font-size:13px;color:#6c7e48}.band{background:var(--ink);color:var(--paper);padding:35px;border-radius:16px}.band p{color:#d0dbd1}.prose{max-width:760px;padding:40px 0}.prose h1{font-size:48px}.notice{border-left:4px solid #8c9e50;padding:16px 24px;background:#ecefdf}footer{border-top:1px solid var(--line);font-size:13px;color:var(--muted);display:flex;justify-content:space-between;gap:20px}footer div{display:flex;gap:22px}:focus-visible{outline:3px solid #8b6f12;outline-offset:5px}@media(max-width:760px){header,main,footer{padding:22px}nav{gap:13px;font-size:12px}.hero{grid-template-columns:1fr;padding:42px 0;gap:26px}h1{letter-spacing:-1.8px}.board{transform:none}.grid{grid-template-columns:1fr;gap:15px}footer{flex-direction:column}.lead{font-size:19px}}`;
const head=(title,desc,robots='index,follow')=>`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title} | ZeroMissed</title><meta name="description" content="${desc}"><meta name="robots" content="${robots}"><meta name="theme-color" content="#193f38"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/styles.css"></head><body><header><a class="brand" href="/">Zero<span>Missed</span></a><nav aria-label="Main navigation"><a href="/#workflow">How it works</a><a href="/privacy/">Privacy</a><a href="/dashboard/">Owner access</a></nav></header><main>`;
const foot=`</main><footer><span>ZeroMissed · Property management, with a clear record.</span><div><a href="/contact/">Contact &amp; support</a><a href="/privacy/">Privacy</a></div></footer></body></html>`;
const pages={
 'index.html':head('Rental operations, kept together','An owner workspace for rental handovers, maintenance, expenses and property records. Private pilot in preparation.')+`<div class="hero"><div><span class="status">PRIVATE PILOT · IN PREPARATION</span><h1>A clear record.<br>A better rental.</h1><p class="lead">Bring handovers, maintenance, people and expenses into one owner workspace—so the next action is easier to see.</p><a class="button" href="#workflow">Explore the workflow</a><a class="button secondary" href="/dashboard/">Owner access status</a></div><aside class="board" aria-label="Illustrative workflow, not live property records"><div class="eyebrow">One place to follow through</div><h3>From request to record.</h3><div class="row"><span>Issue reported</span><span class="tag">Captured</span></div><div class="row"><span>Tenant + vendor appointment</span><span class="tag">Both confirm</span></div><div class="row"><span>Work, invoice + evidence</span><span class="tag">Reviewed</span></div><div class="row"><span>Warranty + next service</span><span class="tag">Recorded</span></div><p class="caption">Illustration of the intended workflow. Live WhatsApp integration is not yet enabled.</p></aside></div><section id="workflow"><div class="eyebrow">The rental lifecycle</div><h2>One property. Every stage.</h2><div class="grid"><article><span class="number">01 / BEFORE MOVE-IN</span><h3>Set expectations clearly.</h3><p>Property-specific terms, dealer coordination and an itemised handover with photographs and open exceptions.</p></article><article><span class="number">02 / DURING TENANCY</span><h3>Follow the work through.</h3><p>Maintenance requests, appointment confirmation, service evidence, warranties and owner-versus-tenant expense records.</p></article><article><span class="number">03 / MOVE-OUT &amp; RESET</span><h3>Compare, review, prepare.</h3><p>Compare condition against the handover record, review proposed deductions and track repairs, cleaning and keys.</p></article></div></section><section><div class="band"><div class="eyebrow">Designed around the people involved</div><h2>The owner sees the overview.<br>Everyone gets a clear next step.</h2><p>The planned communication channel for tenants, dealers and vendors is WhatsApp. The owner workspace is private. Messaging activation and end-to-end pilot testing are still pending.</p></div></section><section><div class="eyebrow">A practical starting point</div><h2>Start with the record.<br>Build confidence through use.</h2><p class="lead">ZeroMissed is being prepared for a privately managed rental portfolio. Public subscriptions, online payments and new customer registrations are not currently available.</p><a href="/contact/">Contact &amp; support information →</a></section>`+foot,
 'dashboard/index.html':head('Owner access status','The private owner workspace is being prepared.','noindex,nofollow')+`<article class="prose"><span class="status">OWNER ACCESS · NOT YET CONNECTED</span><h1>Your workspace is being prepared.</h1><p>The secure hosted owner dashboard is not connected to this website yet. This page does not sign you in or collect your credentials.</p><div class="notice">Continue using your existing review copy until you receive the verified private workspace link. Review-copy changes remain in that browser; export a backup before moving devices.</div><p>WhatsApp activation is pending separately. Tenant and vendor records must not be uploaded to this public website.</p><a class="button" href="/">Return to ZeroMissed</a></article>`+foot,
 'privacy/index.html':head('Privacy information','Information about this public website and the private pilot.','noindex,follow')+`<article class="prose"><div class="eyebrow">PUBLIC WEBSITE / 26 OCTOBER 2026</div><h1>Privacy information</h1><p>This is an informational website for a private rental-management pilot. It has no contact form, document upload, payment checkout or public account registration.</p><h2>Website requests</h2><p>The hosting provider processes technical request information needed to deliver and secure the website. The website code does not add advertising trackers, analytics scripts or third-party fonts.</p><h2>Private rental records</h2><p>This website does not provide access to tenant documents or the owner workspace. Please do not send identity documents or verification codes through public links.</p><h2>Before connected services are activated</h2><p>A separate rental-data notice must identify the responsible owner or operator, contact route, service providers, processing purposes, access controls and retention arrangements. WhatsApp and any AI document or media processing remain subject to that setup and the required permissions.</p><p>Existing tenants should contact their owner through their established communication channel for questions about their rental records.</p></article>`+foot,
 'contact/index.html':head('Contact and support','Contact information for the private pilot.','noindex,follow')+`<article class="prose"><span class="status">PRIVATE PILOT</span><h1>Use your existing contact.</h1><p>If you are an existing tenant, dealer or vendor, continue using the owner’s verified contact already shared with you.</p><p>A dedicated ZeroMissed WhatsApp number and public support channel have not yet been confirmed. There is currently no public signup, paid subscription or online payment collection.</p><div class="notice">For urgent safety issues, use the society’s established emergency or facilities channel immediately. Do not wait for an automated response from this website.</div><a class="button" href="/">Back to ZeroMissed</a></article>`+foot,
 '404.html':head('Page not found','This page is not available.','noindex,nofollow')+`<article class="prose"><div class="eyebrow">404</div><h1>This page isn’t here.</h1><p>Return to the website or check the owner access status.</p><a class="button" href="/">Home</a><a class="button secondary" href="/dashboard/">Owner access status</a></article>`+foot
};
for(const [file,html] of Object.entries(pages)){const target=path.join(dest,file);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,html);}
fs.writeFileSync(path.join(dest,'styles.css'),css);
fs.writeFileSync(path.join(dest,'favicon.svg'),'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#193f38"/><path d="M16 20h32L20 44h28" fill="none" stroke="#dce9a9" stroke-width="6"/></svg>');
fs.writeFileSync(path.join(dest,'robots.txt'),'User-agent: *\nDisallow: /dashboard\nDisallow: /privacy\nDisallow: /contact\nSitemap: https://zeromissed.in/sitemap.xml\n');
fs.writeFileSync(path.join(dest,'sitemap.xml'),'<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>https://zeromissed.in/</loc></url></urlset>');
fs.writeFileSync(path.join(dest,'_headers'),`/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  X-Frame-Options: DENY\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n  Content-Security-Policy: default-src 'none'; style-src 'self'; img-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'\n/dashboard/*\n  Cache-Control: no-store\n  X-Robots-Tag: noindex, nofollow\n`);
fs.writeFileSync(path.join(dest,'_redirects'),'/dashboard /dashboard/ 301\n/privacy /privacy/ 301\n/contact /contact/ 301\n');
console.log('Public website built: '+Object.keys(pages).length+' pages; no private application or portfolio included.');

